with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'パリの通り、雨', 'ギュスターヴ・カイユボット', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Gustave_Caillebotte_-_Paris_Street%2C_Rainy_Day_-_1964.336_-_Art_Institute_of_Chicago.jpg/960px-Gustave_Caillebotte_-_Paris_Street%2C_Rainy_Day_-_1964.336_-_Art_Institute_of_Chicago.jpg', '1877年の第3回印象派展に出品された大作で、現在はシカゴ美術館が所蔵しています。オスマンの改造で生まれたばかりのパリの広い街路と石造りの建物を舞台に、傘をさして行き交う人々を描きました。極端な遠近法と、画面中央に立つ街灯による大胆な分割が目を引きます。素早い筆触の多い印象派のなかでは珍しく、なめらかで写実的な描き方をしているのも特徴です。長く遺族のもとにあり、1964年にシカゴ美術館が収蔵してから広く知られるようになりました。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Gustave_Caillebotte_-_Paris_Street,_Rainy_Day_-_1964.336_-_Art_Institute_of_Chicago.jpg'),
    (2, '紫陽花双鶏図', '伊藤若冲', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/It%C5%8D_Jakuch%C5%AB_-_Rooster_and_Hen_with_Hydrangeas_%28Colorful_Realm_of_Living_Beings%29.jpg/960px-It%C5%8D_Jakuch%C5%AB_-_Rooster_and_Hen_with_Hydrangeas_%28Colorful_Realm_of_Living_Beings%29.jpg', '京都の青物問屋に生まれた伊藤若冲が、およそ10年をかけて描いた30幅の花鳥画「動植綵絵」の一幅です。「動植綵絵」は相国寺に寄進され、のちに皇室に献上されて、いまは皇居三の丸尚蔵館が所蔵する国宝です。青い紫陽花の下で、雄鶏が羽を大きく広げ、雌鶏がそれを見上げています。羽の一枚一枚まで描き込んだ細密さと、鮮やかな色彩が見どころです。同じ題の作品はアメリカのプライス・コレクションにもあり、そちらが先に描かれたとされています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Itō_Jakuchū_-_Rooster_and_Hen_with_Hydrangeas_(Colorful_Realm_of_Living_Beings).jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('都美館で「あなたが世界を読むために」開幕', '東京都美術館の開館100周年記念事業を締め括る企画展が開幕。5人の作家を紹介する。', '東京・上野の東京都美術館で、開館100周年記念事業の締め括りとなる企画展「東京都美術館開館100周年記念 あなたが世界を読むために」が開幕した。会期は2027年1月11日まで。多様な「読み方」による「世界との対話」をテーマに、アルベルト・ジャコメッティ、砂澤ビッキ、谷川俊太郎、エレナ・トゥタッチコワ、山西ももの5人の作品を紹介する。ジャコメッティの章では、作家本人から哲学者の矢内原伊作と美術批評家の宇佐見英治に贈られた作品2点が公開されている。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/report/33358',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('智美術館で「関島寿子 かごについてのかご」', '植物素材でバスケタリー作品を制作する関島寿子の展覧会が東京・虎ノ門で開幕。', '東京・虎ノ門の菊池寛実記念 智美術館で、植物素材を用いたバスケタリー作品を制作する関島寿子の展覧会「関島寿子 かごについてのかご」が開幕した。会期は2027年3月22日まで。関島は1970年代後半にニューヨークに滞在してアメリカの工芸に出会い、帰国後は素材を編む方法「編組」の追求と体系化に取り組んできた。本展では1980年代から最新作までの作品を通じて、その思考と実践をたどる。編む行為を6種類に分類した関島の考えにもとづき、各作品のキャプションには編組の分類が記されている。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/report/33359',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
